1	package relayproof
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// Regression guard for "wait first, then judged replay" inside one advance:
10	// submitting first does not win the nonce. Two messages share
11	// (source, destination, nonce) but differ in proof height; only the one whose
12	// proof height is covered by the trusted header consumes the combination. The
13	// first-submitted message is processed first and goes waiting (proof height
14	// 101 > trusted 100), the second succeeds (proof height 100 <= trusted 100),
15	// and the phase-2 replay sweep then terminalizes the first message in the
16	// same advance — its freshly scheduled backoff must not shield it.
17	//
18	// The report therefore lists the first message twice (waiting, then replay);
